/**
 * IOS-12f's M-f2 (PC-L1, one Chat; plan-12f's Q8 A; VF-PM 2026-11-09 02:24:16Z) — @'S GOLDENS, generated by the Mac's
 * own models (`at-rows.ts`, `composer-draft.ts`). What goes in: the spark, its profiles and the board's facts. What
 * comes out: @'s two groups, the handles, and what a draft says and sends. The phone's port (the kit's `ChatAt` and
 * `ChatDraft`) is held to the same files, copied to `Tests/FieldHomeTests/Fixtures/at-rows/` and pinned byte for byte by
 * `pnpm check:ios-fixtures`. A change to a model changes a golden here, and the kit's row is red until the port follows.
 *
 * A board row goes in as FACTS, not as either side's wire row: the Mac reads `AgentFieldRow`, the phone `AgentRemoteRow`,
 * and the rule is one rule over what they both say. The phone's cut says no persona, so its mapping passes `profileSet`
 * alone (Q3, the retired-sign-in residual, DESIGN.md §8 "The phone's Chat"); that seam is the kit's own row, not a
 * golden. Agents are the catalog's rows (R23b), their labels written as the model read them. The profiles go in as the
 * wire's, written whole, so the kit reads what it decodes. A card chip is the Mac's alone (the hand), so it is no case.
 *
 * `VF_WRITE_GOLDENS=1` writes the files; without it, each file must equal what the models say now, byte for byte.
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  AGENT_CATALOG,
  type AgentFieldRow,
  type AgentModelSelection,
  type AgentPersona,
  type AgentProfileSet,
  type SparkSummary,
} from "@vibefield/contracts";
import { describe, expect, it } from "vitest";
import { AT_WORDS, type AtSources, atRowsOf, sessionHandlesOf } from "../src/chat/at-rows";
import {
  type AgentChip,
  atQueryBefore,
  chipLabel,
  type DraftPart,
  draftMessage,
  draftSendable,
  type SessionChip,
} from "../src/chat/composer-draft";

const here = dirname(fileURLToPath(import.meta.url));
const GOLDENS = join(here, "fixtures/at-rows");
const WRITE = process.env.VF_WRITE_GOLDENS === "1";
const GENERATED =
  "GENERATED by packages/field-app/test/at-rows-goldens.test.ts (VF_WRITE_GOLDENS=1): edit the case there, never here";

/** A golden as the generator writes it: two-space JSON and a final newline, formatted by nothing else. */
const textOf = (golden: unknown): string => `${JSON.stringify(golden, null, 2)}\n`;

/** Written under `VF_WRITE_GOLDENS=1`; else the committed file must be what the models say now, byte for byte. */
function holds(file: string, golden: unknown): void {
  const path = join(GOLDENS, file);
  const text = textOf(golden);
  if (WRITE) {
    mkdirSync(GOLDENS, { recursive: true });
    writeFileSync(path, text);
  }
  expect(readFileSync(path, "utf8"), `${file} is not what the models say now`).toBe(text);
}

// ── the inputs ──

const [A, B, C] = [AGENT_CATALOG[0], AGENT_CATALOG[1], AGENT_CATALOG[2]];
const AT = "2026-10-31T05:00:00.000Z";
const minute = (m: number): string => new Date(Date.parse(AT) + m * 60_000).toISOString();

const persona = (
  profileId: string,
  provider: string,
  set: string,
  loggedIn = true,
): AgentPersona => ({
  profileId,
  provider,
  label: "Default",
  kind: set === "native" ? "native-default" : "managed",
  createdAt: AT,
  set,
  identity: { loggedIn, verifiedAt: AT },
});

const profile = (
  id: string,
  label: string,
  personas: AgentPersona[],
  kind: "native" | "managed" = "managed",
): AgentProfileSet => ({ id, kind, label, default: kind === "native", createdAt: AT, personas });

const SETS: AgentProfileSet[] = [
  profile(
    "native",
    "This Mac",
    [
      persona(`${A.id}:native-default`, A.id, "native"),
      persona(`${B.id}:native-default`, B.id, "native"),
      persona(`${C.id}:native-default`, C.id, "native", false),
    ],
    "native",
  ),
  profile("work", "Work", [persona("work-a", A.id, "work")]),
  profile("home", "Home", [persona("home-b", B.id, "home")]),
];

/** What a board row says, on either side's wire. */
interface Facts {
  readonly run: string;
  readonly agent: string;
  readonly label: string;
  readonly project: string | null;
  readonly status: "working" | "idle" | "blocked" | "unknown";
  readonly blockers: number;
  readonly alive: boolean;
  readonly spark: string | null;
  readonly origin: { readonly by: string; readonly spark: string | null } | null;
  readonly profileSet: string | null;
  readonly profileId: string | null;
  readonly createdAt: string;
  readonly stateChangedAt: string;
  readonly lastActivityAt: string | null;
}

const facts = (over: Partial<Facts> & Pick<Facts, "run">): Facts => ({
  agent: A.id,
  label: A.label,
  project: null,
  status: "idle",
  blockers: 0,
  alive: true,
  spark: null,
  origin: null,
  profileSet: null,
  profileId: null,
  createdAt: AT,
  stateChangedAt: AT,
  lastActivityAt: null,
  ...over,
});

const BOARD: Facts[] = [
  // the person's own, no persona named, so This Mac's: Working, the newest activity
  facts({
    run: "run-his-1",
    status: "working",
    project: "vibe-field",
    createdAt: minute(1),
    lastActivityAt: minute(30),
  }),
  // filed under Work, the same folder's name, started later: its ordinal
  facts({
    run: "run-his-2",
    profileSet: "work",
    profileId: "work-a",
    origin: { by: "you", spark: null },
    project: "vibe-field",
    createdAt: minute(2),
    lastActivityAt: minute(10),
  }),
  // filed under neither, its persona listed by Work: placed by the persona
  facts({
    run: "run-persona",
    profileId: "work-a",
    project: "ice",
    createdAt: minute(3),
    stateChangedAt: minute(5),
  }),
  // one this spark started, blocked on the person
  facts({
    run: "run-mine",
    agent: B.id,
    label: B.label,
    profileSet: "native",
    origin: { by: "spark", spark: "sp-vela0001" },
    status: "blocked",
    blockers: 1,
    project: "rosetta",
    createdAt: minute(4),
    lastActivityAt: minute(20),
  }),
  // not heard yet: no word for what it is doing
  facts({
    run: "run-unheard",
    status: "unknown",
    project: "mille",
    createdAt: minute(6),
    lastActivityAt: minute(2),
  }),
  // no folder: its agent's label is its name
  facts({ run: "run-nofolder", createdAt: minute(5), lastActivityAt: minute(1) }),
  // never rows: its own session, another spark's own, another spark's agent, a flow's run, a profile it lacks, a
  // retired sign-in no profile lists, an ended run, an origin word this build does not know
  facts({ run: "run-vela", spark: "sp-vela0001", project: "vela" }),
  facts({ run: "run-lyra", spark: "sp-lyra0001", project: "lyra" }),
  facts({ run: "run-lyra-agent", origin: { by: "spark", spark: "sp-lyra0001" }, project: "x" }),
  facts({ run: "run-flow", origin: { by: "flow", spark: null }, project: "x" }),
  facts({ run: "run-home", profileSet: "home", profileId: "home-b", project: "x" }),
  facts({ run: "run-retired", profileId: "gone", project: "x" }),
  facts({ run: "run-ended", alive: false, project: "x" }),
  facts({ run: "run-odd", origin: { by: "someone", spark: null }, project: "x" }),
];

/** The Mac's row for a run's facts. */
const rowOf = (f: Facts): AgentFieldRow => ({
  runtimeRunId: f.run,
  revision: 1,
  kind: f.agent,
  label: f.label,
  tier: "managed",
  device: "dev-1",
  status: f.status,
  statusSince: AT,
  stateChangedAt: f.stateChangedAt,
  createdAt: f.createdAt,
  alive: f.alive,
  blockers:
    f.blockers === 0
      ? []
      : [{ id: "q", kind: "question", since: AT } as AgentFieldRow["blockers"][0]],
  ...(f.project === null ? {} : { project: { name: f.project } }),
  ...(f.spark === null ? {} : { spark: f.spark }),
  ...(f.origin === null
    ? {}
    : {
        origin: { by: f.origin.by, ...(f.origin.spark === null ? {} : { spark: f.origin.spark }) },
      }),
  ...(f.profileSet === null ? {} : { profileSet: f.profileSet }),
  ...(f.profileId === null ? {} : { profileId: f.profileId }),
  ...(f.lastActivityAt === null ? {} : { lastActivityAt: f.lastActivityAt }),
});

const spark = (id: string, name: string, profiles: string[], run: string | null): SparkSummary => ({
  id,
  name,
  face: { seed: 7 },
  agent: A.id,
  profiles,
  thinksUnder: profiles[0] ?? "native",
  folder: `/f/${name.toLowerCase()}`,
  createdAt: AT,
  updatedAt: AT,
  ...(run === null ? {} : { session: { runtimeRunId: run, terminalSessionId: "pty", live: true } }),
});

const SPARKS = {
  /** two profiles: a row per agent and profile, each with its pill */
  vela: spark("sp-vela0001", "Vela", ["native", "work"], "run-vela"),
  /** one profile: no pill, and "under ‹profile›" is never said */
  solo: spark("sp-solo0001", "Solo", ["native"], null),
  /** a profile with no sign-in and no session: nothing to offer */
  bare: spark("sp-bare0001", "Bare", ["empty"], null),
} as const;

const SETS_WITH_EMPTY = [...SETS, profile("empty", "Empty", [])];

type Read = "read" | "reading" | "failed";

interface RowsCase {
  readonly name: string;
  readonly spark: keyof typeof SPARKS;
  readonly query: string;
  readonly sets: Read;
  readonly board: Read;
}

const ROWS_CASES: readonly RowsCase[] = [
  { name: "both groups, nearest last", spark: "vela", query: "", sets: "read", board: "read" },
  { name: "one profile: no pill", spark: "solo", query: "", sets: "read", board: "read" },
  {
    name: "the query filters agents",
    spark: "vela",
    query: B.label.slice(-3),
    sets: "read",
    board: "read",
  },
  {
    name: "the query filters by handle",
    spark: "vela",
    query: "vibe",
    sets: "read",
    board: "read",
  },
  {
    name: "the query filters by the pill",
    spark: "vela",
    query: "wor",
    sets: "read",
    board: "read",
  },
  { name: "the handle keeps its ordinal", spark: "vela", query: "·2", sets: "read", board: "read" },
  { name: "nothing matches", spark: "vela", query: "zzz", sets: "read", board: "read" },
  { name: "nothing to offer", spark: "bare", query: "", sets: "read", board: "read" },
  { name: "the profiles are being read", spark: "vela", query: "", sets: "reading", board: "read" },
  { name: "the board is being read", spark: "vela", query: "", sets: "read", board: "reading" },
  { name: "the profiles can't be read", spark: "vela", query: "", sets: "failed", board: "read" },
  { name: "the board can't be read", spark: "vela", query: "", sets: "read", board: "failed" },
  {
    name: "the board can't be read, nothing matches",
    spark: "vela",
    query: "zzz",
    sets: "read",
    board: "failed",
  },
];

const setsOf = (read: Read): AtSources["sets"] =>
  read === "read" ? SETS_WITH_EMPTY : read === "reading" ? null : "failed";
const boardOf = (read: Read): AtSources["rows"] =>
  read === "read" ? BOARD.map(rowOf) : read === "reading" ? null : "failed";

function rowsGolden() {
  return {
    "//": GENERATED,
    labels: Object.fromEntries([A, B, C].map((entry) => [entry.id, entry.label])),
    sets: SETS_WITH_EMPTY,
    sparks: Object.fromEntries(
      Object.entries(SPARKS).map(([key, value]) => [
        key,
        {
          id: value.id,
          name: value.name,
          profiles: value.profiles,
          run: value.session?.runtimeRunId ?? null,
        },
      ]),
    ),
    board: BOARD,
    words: {
      agents: AT_WORDS.agents,
      sessions: AT_WORDS.sessions,
      reading: AT_WORDS.reading,
      none: AT_WORDS.none("zzz"),
      empty: AT_WORDS.empty("Bare"),
      failed: AT_WORDS.failed,
      sessionsFailed: AT_WORDS.sessionsFailed,
    },
    handles: Object.fromEntries(
      Object.entries(SPARKS).map(([key, value]) => [
        key,
        Object.fromEntries(sessionHandlesOf(value, boardOf("read"), setsOf("read"))),
      ]),
    ),
    cases: ROWS_CASES.map((rowsCase) => ({
      ...rowsCase,
      list: atRowsOf({
        spark: SPARKS[rowsCase.spark],
        query: rowsCase.query,
        sets: setsOf(rowsCase.sets),
        rows: boardOf(rowsCase.board),
      }),
    })),
  };
}

// ── the draft ──

const SELECTION = { kind: "model" } as unknown as AgentModelSelection;

const agentChip = (over: Partial<AgentChip> = {}): AgentChip => ({
  id: "c-agent",
  kind: "agent",
  agent: A.id,
  label: A.label,
  profile: { id: "work", name: "Work" },
  named: false,
  model: null,
  ...over,
});

const MODEL = { words: ["Opus 5.5", "high"], selection: SELECTION };

const sessionChip = (over: Partial<SessionChip> = {}): SessionChip => ({
  id: "c-session",
  kind: "session",
  session: "run-his-2",
  agent: A.id,
  label: A.label,
  handle: "vibe-field·2",
  project: "vibe-field",
  ...over,
});

const text = (value: string): DraftPart => ({ kind: "text", text: value });
const chip = (value: AgentChip | SessionChip): DraftPart => ({ kind: "chip", chip: value });

/** A chip as the golden writes it: what the port draws and sends, and never the picker's opaque selection. */
const said = (value: AgentChip | SessionChip) =>
  value.kind === "agent"
    ? { ...value, model: value.model === null ? null : { words: value.model.words } }
    : value;

const partSaid = (part: DraftPart) =>
  part.kind === "text" ? part : { kind: "chip", chip: said(part.chip as AgentChip | SessionChip) };

const CHIPS: readonly (AgentChip | SessionChip)[] = [
  agentChip(),
  agentChip({ model: MODEL }),
  agentChip({ named: true }),
  agentChip({ named: true, model: MODEL }),
  sessionChip(),
  sessionChip({ project: null, handle: A.label }),
];

const MESSAGES: readonly {
  readonly name: string;
  readonly parts: readonly DraftPart[];
  readonly pending: string | null;
}[] = [
  { name: "words alone", parts: [text("look at this")], pending: null },
  { name: "words, trimmed at both ends", parts: [text("  look  ")], pending: null },
  {
    name: "an agent, in the sentence",
    parts: [text("ask "), chip(agentChip()), text(" to look")],
    pending: null,
  },
  {
    name: "an agent at a model, under a profile",
    parts: [chip(agentChip({ named: true, model: MODEL })), text(" please")],
    pending: null,
  },
  {
    name: "a session carries its run's id",
    parts: [text("tell "), chip(sessionChip()), text(" to stop")],
    pending: null,
  },
  {
    name: "a session with no folder",
    parts: [chip(sessionChip({ project: null, handle: A.label }))],
    pending: null,
  },
  {
    name: "two chips, spans in order",
    parts: [chip(agentChip()), text(" and "), chip(sessionChip())],
    pending: null,
  },
  {
    name: "UTF-16 offsets past an emoji",
    parts: [text("🙂 ask "), chip(agentChip())],
    pending: null,
  },
  {
    name: "a chip at the end, the trailing space trimmed",
    parts: [chip(agentChip()), text(" ")],
    pending: null,
  },
  { name: "only the @ being typed", parts: [text("@cla")], pending: "@cla" },
  { name: "words before the @ being typed", parts: [text("hi @cla")], pending: "@cla" },
  {
    name: "a chip while an @ is being typed",
    parts: [chip(agentChip()), text(" @x")],
    pending: "@x",
  },
  { name: "nothing", parts: [], pending: null },
  { name: "only a space", parts: [text(" ")], pending: null },
];

const QUERIES: readonly string[] = [
  "",
  "@",
  "@cla",
  "hi @cla",
  "hi @",
  "hi\n@cla",
  "a@b",
  "@a @b",
  "@a b",
  "mail me@x.dev",
  "@@",
  "hi @cla ",
];

function draftGolden() {
  return {
    "//": GENERATED,
    queries: QUERIES.map((before) => ({ before, found: atQueryBefore(before) })),
    chips: CHIPS.map((value) => ({ chip: said(value), label: chipLabel(value) })),
    messages: MESSAGES.map((message) => ({
      name: message.name,
      parts: message.parts.map(partSaid),
      pending: message.pending,
      message: draftMessage(message.parts),
      sendable: draftSendable(message.parts, message.pending),
    })),
  };
}

// ── the rows ──

describe("@'s goldens (IOS-12f's M-f2): what the Mac's models say, for the phone's port", () => {
  it("@'s two groups, its words and the handles", () => {
    holds("at-rows.rows.golden.json", rowsGolden());
  });

  it("what a draft says, and what a send carries", () => {
    holds("at-rows.draft.golden.json", draftGolden());
  });
});
